from html import escape

def render_about(page):
    content = '''<section class="ab-hero"><div class="ab-hero-copy"><p class="ab-eyebrow">About Modern Group</p><h1>Specialist roots.<br>Shared direction.</h1><p class="ab-lead">A shared commercial identity connecting three specialized manufacturing companies in Jiangsu, China.</p><p>MDHI, MMEC and MEEM share executive leadership and unified governance standards while remaining separate operating companies.</p><a class="ab-link" href="#development">Discover our story <span aria-hidden="true">↓</span></a></div><figure class="ab-hero-photo"><img src="../assets/images/about-four-product-lines-original.webp" alt="Illustration of structural steel, modular plants, air-cooled heat exchangers and HRSG pressure parts" width="1600" height="1200" fetchpriority="high" decoding="async"><figcaption>Structural steel · Modular plants<br>HRSG pressure parts · Air-cooled heat exchangers</figcaption></figure></section>
<div class="ab-facts" aria-label="Group overview"><div><strong>03</strong><span>Operating companies</span></div><div><strong>04</strong><span>Product lines</span></div><p>Shared leadership.<br>Company-level responsibility.</p></div>
<section class="ab-section ab-development" id="development" aria-labelledby="ab-history-title"><div class="ab-heading"><div><p class="ab-eyebrow">01 / Our development</p><h2 id="ab-history-title">Built on specialist expertise.</h2></div><p>Each milestone adds a distinct capability to our manufacturing network.</p></div><div class="ab-milestones">'''
    milestones = [
        ('2010','MDHI founded','about-mdhi-founded-meeting.webp','MDHI team in a technical project discussion','Modern Heavy Industries (Taicang) Co., Ltd. was founded, establishing the structural steel and industrial fabrication capabilities behind the network.'),
        ('2017','MMEC founded','about-mmec-chairman.webp','Composite image of the chairman presenting the MMEC factory plan','Modern Modular Engineering & Construction Co., Ltd. was founded. Its port-adjacent modular yard added integrated-module capability to the network.'),
        ('2025','MEEM facility opens','about-meem-opening.webp','MEEM facility grand opening ceremony','A dedicated manufacturing facility for HRSG pressure parts and air-cooled heat exchangers opened, completing the current four-product-line network.')
    ]
    for year,title,image,alt,copy in milestones:
        photo = f'<img src="../assets/images/{image}" alt="{alt}" loading="lazy" decoding="async">'
        if image == 'about-mdhi-founded-meeting.webp':
            photo = f'<div class="ab-milestone-photo ab-milestone-photo--people">{photo}</div>'
        content += f'<article class="ab-milestone"><div class="ab-year">{year}<span aria-hidden="true">↗</span></div>{photo}<h3>{title}</h3><p>{escape(copy)}</p></article>'
    content += '''</div></section><section class="ab-section ab-structure" aria-labelledby="ab-structure-title"><div class="ab-heading"><div><p class="ab-eyebrow">02 / Group structure</p><h2 id="ab-structure-title">One identity.<br>Three operating companies.</h2></div><p>Shared standards connect our companies. Each brings its own manufacturing scope and remains accountable for its projects.</p></div><div class="ab-companies">'''
    companies=[('MDHI','Taicang','Modern Heavy Industries (Taicang) Co., Ltd.','Structural steel','Steel structures for buildings, infrastructure and industrial projects.'),('MMEC','Zhangjiagang','Modern Modular Engineering & Construction Co., Ltd.','Structural steel · Modular plants','Structural fabrication, module assembly and port-oriented logistics.'),('MEEM','Zhangjiagang','Modern Energy Equipment Manufacturing Co., Ltd.','HRSG pressure parts · Air-cooled heat exchangers','Energy equipment for power generation and process applications.')]
    for code,city,legal,scope,copy in companies:
        content += f'<article class="ab-company"><p class="ab-city">{city}</p><h3>{code}</h3><p class="ab-legal-name">{escape(legal)}</p><div class="ab-company-scope"><h4>{escape(scope)}</h4><p>{copy}</p></div><a class="ab-link" href="../{code.lower()}/index.html">Explore {code} <span aria-hidden="true">→</span></a></article>'
    content += '''</div><p class="ab-legal-note"><span>Company-level accountability</span>Modern Group is a commercial brand, not a separate legal entity. Contracts, certifications and project responsibilities remain with the relevant operating company.</p></section>
<section class="ab-section ab-governance" aria-labelledby="ab-governance-title"><div class="ab-governance-copy"><p class="ab-eyebrow">03 / Governance &amp; policies</p><h2 id="ab-governance-title">Clear standards.<br>Defined accountability.</h2><p>Group policies define expectations for legal compliance, ethical conduct, fair employment, quality and responsible operations.</p><div class="ab-responsibility"><div><strong>Group leadership</strong><p>Sets group policy and oversees management.</p></div><span aria-hidden="true">↓</span><div><strong>Operating companies</strong><p>Apply standards and remain accountable.</p></div></div></div><ol class="ab-policies">'''
    for label,detail in [('Legal & Regulatory Compliance','Operate within applicable legal and regulatory requirements.'),('Code of Business Conduct','Set clear expectations for ethical business conduct.'),('Fair Employment','Support fair and responsible employment practices.'),('Quality Assurance','Apply quality standards throughout manufacturing operations.'),('Social & Environmental Compliance','Promote responsible operations for people and the environment.')]:
        content += f'<li><h3>{escape(label)}</h3><p>{detail}</p></li>'
    content += '''</ol></section><section class="ab-next"><div><p class="ab-eyebrow">Explore the network</p><h2>Meet the companies.<br>Start a conversation.</h2></div><div class="ab-next-links"><a class="button button-gold" href="../companies-locations/index.html">Explore our companies <span aria-hidden="true">→</span></a><a class="ab-link" href="../contact/index.html">Discuss your project <span aria-hidden="true">↗</span></a></div></section>'''
    return page('About Modern Group | Modern Group',1,'About','','','',content,'A shared commercial identity connecting three specialized manufacturing companies in Jiangsu, China.')
